export function classifyFailure({ statusCode: status, headers, message, body = '' }) {
    const text = `${message} ${body}`;
    if (quotaExhaustedText(text)) {
        return { rotate: true, cooldownMs: EXHAUSTED_COOLDOWN_MS };
    }
    if (status === 402)
        return { rotate: true, cooldownMs: EXHAUSTED_COOLDOWN_MS };
    if (overloadedText(text)) {
        return { rotate: true, cooldownMs: retryAfterMs(headers) ?? OVERLOADED_COOLDOWN_MS };
    }
    if (status === 429)
        return { rotate: true, cooldownMs: rotateCooldownMs(headers) };
    if (status === 401 || status === 403)
        return { rotate: true, cooldownMs: rotateCooldownMs(headers) };
    if (rotateWorthyText(text)) {
        return { rotate: true, cooldownMs: rotateCooldownMs(headers) };
    }
    return null;
}
/** Permanent OAuth refresh death (invalid_grant / expired refresh). */
export function isPermanentRefreshFailure(error) {
    const message = error instanceof Error ? error.message : typeof error === 'string' ? error : '';
    const haystack = message.toLowerCase();
    if (!haystack)
        return false;
    if (haystack.includes('invalid_grant'))
        return true;
    if (haystack.includes('refresh token expired'))
        return true;
    if (haystack.includes('refresh_token') || haystack.includes('refresh token')) {
        return haystack.includes('expired') || haystack.includes('invalid') || haystack.includes('revoked');
    }
    return false;
}
